sys_script_include.script:
function MakePascalCase(strInput)
{
	strInput = GetStringValue(strInput);
	strInput = strInput.trim();
	if (strInput == '')
	{
		return '';
	}

	if (IsPascalCase(strInput) == true)
	{
		return strInput;
	}

	//var words = strInput.split(/[\s_\-\.\t\/]+/);
	var words = strInput.split(/[^\p{L}\p{N}]+/u);
	var strPascalCase = '';
	for (var i = 0; i < words.length; i++)
	{
		var word = words[i];
		if (word.length === 0)
			continue;

		var firstChar = word.charAt(0);
		var rest = word.substring(1);

		if (firstChar >= '0' && firstChar <= '9')
		{
			// If first char is digit, keep as is, capitalize rest normally
			strPascalCase += firstChar + rest.charAt(0).toUpperCase() + rest.substring(1);
		}
		else
		{
			// Preserve original casing of rest if original word is all uppercase
			if (word === word.toUpperCase())
			{
				strPascalCase += firstChar.toUpperCase() + rest;
			}
			else
			{
				strPascalCase += firstChar.toUpperCase() + rest.toLowerCase();
			}
		}
	}

	return strPascalCase;
}
